/* Portable case archives. Real PDFs remain binary ZIP entries, not localStorage. */
let localProjectService=false;
async function projectArchive(){const c=structuredClone(current()),zip=new JSZip();if(!c)throw Error('請先開啟案件');const sourceIds=[...new Set(c.files.map(f=>f.sourceId).filter(Boolean))];for(let i=0;i<sourceIds.length;i++){const id=sourceIds[i],blob=await pdfStore('get',id);if(!blob)throw Error('找不到原始 PDF，無法建立完整備份');zip.file('sources/'+i+'.pdf',blob);}zip.file('project.json',JSON.stringify({format:'drawing-desk-project',version:1,case:c,sources:sourceIds.map((id,i)=>({id,path:'sources/'+i+'.pdf'})),logs:logs.filter(l=>l.caseId===c.id)}));return zip.generateAsync({type:'blob',compression:'STORE'});}
function offerProjectDownload(blob,name){const url=URL.createObjectURL(blob);caseDialog('backupDownload',`<h2>案件備份已建立</h2><p>包含原始 PDF、頁面編輯及操作歷史。</p><a class="primary download-link" href="${url}" download="${esc(name)}">下載案件備份</a><button onclick="this.closest('dialog').close()">關閉</button>`);$('#backupDownload').addEventListener('close',()=>URL.revokeObjectURL(url),{once:true});}
async function backupProject(){try{offerProjectDownload(await projectArchive(),current().name+'.drawing.zip');}catch(e){notify('備份失敗：'+e.message);}}
function openProjectRestore(){caseDialog('restoreProjectDialog','<h2>還原案件備份</h2><p>建立獨立案件，不覆蓋既有案件。只接受本系統的 .drawing.zip 備份。</p><input type="file" accept=".zip" onchange="restoreProjectFile(this.files[0])"><p id="restoreStatus" role="status"></p><button onclick="this.closest(\'dialog\').close()">關閉</button>');}
function validateProject(manifest){function scrub(value){if(!value||typeof value!=='object')return;for(const [k,v] of Object.entries(value)){if(k==='html'&&typeof v==='string')value[k]=cleanNoteHtml(v);else if(typeof v==='object')scrub(v);}}scrub(manifest);if(manifest?.format!=='drawing-desk-project'||manifest.version!==1||!Array.isArray(manifest.case?.files)||!Array.isArray(manifest.sources))throw Error('備份格式或版本不符');if(manifest.case.files.length>5000)throw Error('備份頁數過多');const ids=new Set(manifest.sources.map(s=>s.id));for(const f of manifest.case.files){if(f.sourceId&&!ids.has(f.sourceId))throw Error('缺少來源檔案對照');if(f.sourceId&&(!Number.isFinite(f.width)||!Number.isFinite(f.height)||f.width<=0||f.height<=0||!Number.isInteger(f.pageIndex)||f.pageIndex<0))throw Error('頁面資料無效');if(![0,90,180,270].includes(f.rotation||0))throw Error('旋轉資料無效');for(const key of ['masks','notes']){if(!Array.isArray(f[key]))throw Error('物件資料無效');for(const o of f[key]){if(!['x','y','w','h'].every(k=>Number.isFinite(o[k])&&o[k]>=0&&o[k]<=100))throw Error('物件範圍無效');if(o.html)o.html=cleanNoteHtml(o.html);if(!/^#[0-9a-f]{6}$/i.test(o.color||''))throw Error('色彩資料無效');}}}return manifest;}
async function restoreProjectFile(upload){if(!upload)return;const stored=[];const status=$('#restoreStatus');if(status)status.textContent='正在檢查並還原…';try{if(upload.size>1024*1024*1024)throw Error('備份超過 1 GB');const zip=await JSZip.loadAsync(upload),entry=zip.file('project.json');if(!entry)throw Error('找不到案件資料');const m=validateProject(JSON.parse(await entry.async('string'))),c=m.case,map=new Map();for(const src of m.sources){if(!/^sources\/\d+\.pdf$/.test(src.path))throw Error('來源路徑無效');const entry=zip.file(src.path);if(!entry)throw Error('缺少原始 PDF');const blob=await entry.async('blob'),bytes=await blob.arrayBuffer(),pages=await pdfCall('inspect',{bytes});for(const f of c.files.filter(p=>p.sourceId===src.id)){if(f.pageIndex>=pages.length)throw Error('來源 PDF 頁數不符');}const id=crypto.randomUUID();await pdfStore('put',id,blob);stored.push(id);map.set(src.id,id);}c.id='RFQ-'+crypto.randomUUID();c.name=String(c.name||'還原案件')+'（還原）';c.savedAt=new Date().toISOString();c.files.forEach(f=>{if(f.sourceId)f.sourceId=map.get(f.sourceId);});const restoredLogs=(Array.isArray(m.logs)?m.logs:[]).map(l=>({...l,caseId:c.id})),nextLogs=[...logs,...restoredLogs],next=[c,...cases];if(!writeCaseStore(next,nextLogs))throw Error('案件資訊儲存失敗');cases=next;logs=nextLogs;cid=c.id;fi=0;$('#restoreProjectDialog')?.close();go('case');notify('案件已完整還原');}catch(e){for(const id of stored)await pdfStore('delete',id).catch(()=>{});if(status)status.textContent='還原失敗：'+e.message;else notify(e.message);}}
const backupCasePage=casePage;casePage=function(){return backupCasePage()+`<section class="card" style="margin-top:20px"><h2>案件備份</h2><p>包含原始 PDF 與編輯資料，可搬移到本機測試版。</p><div class="actions"><button onclick="backupProject()">下載案件備份</button>${localProjectService?'<button onclick="saveLocalProject()">另存本機案件</button>':''}</div></section>`;};
const restoreCasesPage=casesPage;casesPage=function(){return restoreCasesPage()+`<div class="actions" style="margin-top:16px"><button onclick="openProjectRestore()">還原案件備份</button>${localProjectService?'<button onclick="openLocalProjects()">開啟本機已存案件</button>':''}</div>`;};
async function saveLocalProject(){try{const blob=await projectArchive(),res=await fetch('/api/projects/'+encodeURIComponent(current().id),{method:'PUT',headers:{'Content-Type':'application/zip'},body:blob});if(!res.ok)throw Error('本機儲存服務回應失敗');notify('案件與原始 PDF 已儲存到本機資料夾');}catch(e){notify('本機儲存失敗：'+e.message);}}
async function openLocalProjects(){try{const res=await fetch('/api/projects'),items=await res.json();caseDialog('localProjectsDialog',`<h2>本機已存案件</h2><p>開啟時還原為獨立副本，不覆蓋瀏覽器案件。</p>${items.map(p=>`<button class="local-project" data-id="${esc(p.id)}" onclick="loadLocalProject(this.dataset.id)">${esc(p.name)} · ${esc(p.updated)}</button>`).join('')||'<p>尚未儲存本機案件</p>'}<button onclick="this.closest('dialog').close()">關閉</button>`);}catch(e){notify('無法讀取本機案件');}}
async function loadLocalProject(id){try{const r=await fetch('/api/projects/'+encodeURIComponent(id));if(!r.ok)throw Error('找不到本機案件');$('#localProjectsDialog')?.close();await restoreProjectFile(await r.blob());}catch(e){notify(e.message);}}
if(['localhost','127.0.0.1'].includes(location.hostname))fetch('/api/health').then(r=>r.ok?r.json():null).then(r=>{if(r?.service==='drawing-desk-local'){localProjectService=true;render();}}).catch(()=>{});
render();
